def first_free_locker(taken):
    n = len(taken)
    for i in range(n):
        while 1 <= taken[i] <= n and taken[taken[i] - 1] != taken[i]:
            slot = taken[i] - 1
            taken[i], taken[slot] = taken[slot], taken[i]
    for i in range(n):
        if taken[i] != i + 1:
            return i + 1
    return n + 1
